using Marketplace.Domain.Common; namespace Marketplace.Domain.Carts; public sealed class CartItem:Entity<long>{private CartItem(){} public long CartId{get;private set;} public long ProductVariantId{get;private set;} public long ProductId{get;private set;} public long StoreId{get;private set;} public int Quantity{get;private set;} public long CachedUnitPriceIRR{get;private set;} public long? WarrantyId{get;private set;} public long WarrantyPriceIRR{get;private set;} public static CartItem Create(long id,long cartId,long productId,long variantId,long storeId,int qty,long price,long? warrantyId,long warrantyPrice){if(qty<=0||price<0||warrantyPrice<0)throw new DomainException("Invalid cart item.");return new(){Id=id,CartId=cartId,ProductId=productId,ProductVariantId=variantId,StoreId=storeId,Quantity=qty,CachedUnitPriceIRR=price,WarrantyId=warrantyId,WarrantyPriceIRR=warrantyPrice};} public void ChangeQuantity(int q){if(q<=0)throw new DomainException("Quantity must be positive.");Quantity=q;} public void SetWarranty(long? id,long price){if(price<0)throw new DomainException("Warranty price cannot be negative.");WarrantyId=id;WarrantyPriceIRR=price;} public void SetCachedUnitPrice(long p){if(p<0)throw new DomainException("Price cannot be negative.");CachedUnitPriceIRR=p;} }
